const f = reformer.form();
f.step("Покупатель").fields("customerType","contact.lastName","contact.firstName","email","phone","birthDate");
f.step("Компания").fields("company.name","company.inn").after("Покупатель");
f.step("Доставка").fields("deliveryMethod","deliveryAddress.city","deliveryAddress.street","deliveryAddress.house","deliveryDate","billingSame","billingAddress.city","billingAddress.street","billingAddress.house").after("Компания");
f.step("Товары").fields("items","subtotal").after("Доставка");
f.step("Оплата").fields("promoCode","discount","total","paymentMethod","receiptEmail","comment").after("Товары");
f.step("Подтверждение").fields("recipients","agreeTerms","newsletter","sources").after("Оплата");
f.field("company.name").showWhen(m=>m.customerType==="company");
f.field("company.inn").showWhen(m=>m.customerType==="company");
f.field("phone").mask("+7 (999) 999-99-99");
f.submit("Оформить заказ","submitOrder");
console.log(await f.save());

const f = reformer.form();
const notPickup = m=>m.deliveryMethod!=="pickup";
f.field("deliveryAddress.city").required("Введите город").when(notPickup);
f.field("deliveryAddress.street").required("Введите улицу").when(notPickup);
f.field("deliveryAddress.house").required("Введите дом").when(notPickup);
for (const k of ["city","street","house"]) f.field("deliveryAddress."+k).disableWhen(m=>m.deliveryMethod==="pickup",{resetOnDisable:true});
f.field("deliveryDate").type("date").required("Выберите дату доставки").future("Дата доставки — не раньше завтрашнего дня").when(m=>m.deliveryMethod==="courier");
f.field("deliveryDate").showWhen(m=>m.deliveryMethod==="courier");
f.field("deliveryDate").resetWhen(m=>m.deliveryMethod!=="courier");
const diff = m=>!m.billingSame;
f.field("billingAddress.city").required("Введите город").when(diff).copyFrom("deliveryAddress.city",m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("billingAddress.street").required("Введите улицу").when(diff).copyFrom("deliveryAddress.street",m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("billingAddress.house").required("Введите дом").when(diff).copyFrom("deliveryAddress.house",m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("company.inn").rule("innChecksum","Неверная контрольная сумма ИНН");
f.field("promoCode").transform(v=>String(v).toUpperCase()).asyncCheck(v=>!v||v==="SALE10"||v==="SALE20",{delay:300,message:"Промокод не найден"});
f.field("discount").min(0,"Скидка не может быть отрицательной").max(30,"Скидка не больше 30%").enableWhen(m=>m.customerType==="company",{resetOnDisable:true});
f.field("total").compute(m=>Math.round(m.subtotal*(1-m.discount/100)*100)/100).warning(m=>m.total<=100000,"Крупный заказ: менеджер свяжется для подтверждения");
f.field("subtotal").compute(m=>m.items.reduce((s,r)=>s+(Number(r.quantity)||0)*(Number(r.price)||0),0));
f.field("paymentMethod").required("Выберите способ оплаты").options([{value:"card",label:"Картой онлайн"},{value:"cash",label:"При получении"},{value:"invoice",label:"По счёту"}]);
f.field("paymentMethod").check(m=>m.paymentMethod!=="invoice"||m.customerType==="company","Оплата по счёту — только для юридических лиц");
f.field("paymentMethod").setOnChange("customerType",m=>m.customerType==="person"&&m.paymentMethod==="invoice","card");
f.field("receiptEmail").email("Некорректный email для чека").sync("email");
f.field("comment").maxLength(500,"Не больше 500 символов");
f.field("agreeTerms").required("Нужно принять условия оферты").check(m=>m.agreeTerms===true,"Нужно принять условия оферты");
f.field("sources").options([{value:"search",label:"Поиск"},{value:"friends",label:"Друзья"},{value:"ads",label:"Реклама"},{value:"other",label:"Другое"}]).optional();
f.field("items").removeRule("minLength");f.field("items").removeRule("maxLength");
f.array("items","Товары",{min:1,max:10});
console.log(await f.save());

